static void wipe(void *p,size_t n){volatile uint8_t *b=(volatile uint8_t *)p;while(n--!=0U)*b++=0U;}
static uint8_t xt(uint8_t v){return (uint8_t)((uint8_t)(v<<1U)^((v&0x80U)!=0U?0x1bU:0U));}
static void expand(const uint8_t k[16],uint8_t r[176]){uint8_t t[4],rc=1U;size_t n=16U,i;memcpy(r,k,16U);while(n<176U){for(i=0;i<4U;i++)t[i]=r[n-4U+i];if((n%16U)==0U){uint8_t q=t[0];t[0]=link_aes_sbox[t[1]];t[1]=link_aes_sbox[t[2]];t[2]=link_aes_sbox[t[3]];t[3]=link_aes_sbox[q];t[0]^=rc;rc=xt(rc);}for(i=0;i<4U;i++){r[n]=r[n-16U]^t[i];n++;}}wipe(t,sizeof(t));}
static void add(uint8_t s[16],const uint8_t*r){size_t i;for(i=0;i<16U;i++)s[i]^=r[i];}
static void sub(uint8_t s[16]){size_t i;for(i=0;i<16U;i++)s[i]=link_aes_sbox[s[i]];}
static void shift(uint8_t s[16]){uint8_t t;t=s[1];s[1]=s[5];s[5]=s[9];s[9]=s[13];s[13]=t;t=s[2];s[2]=s[10];s[10]=t;t=s[6];s[6]=s[14];s[14]=t;t=s[3];s[3]=s[15];s[15]=s[11];s[11]=s[7];s[7]=t;}
static void mix(uint8_t s[16]){size_t c;for(c=0;c<4U;c++){uint8_t*v=&s[c*4U];uint8_t a=v[0]^v[1]^v[2]^v[3],f=v[0];v[0]^=a^xt((uint8_t)(v[0]^v[1]));v[1]^=a^xt((uint8_t)(v[1]^v[2]));v[2]^=a^xt((uint8_t)(v[2]^v[3]));v[3]^=a^xt((uint8_t)(v[3]^f));}}
bool link_aes128_encrypt_block(const uint8_t k[16],const uint8_t in[16],uint8_t out[16]){uint8_t s[16],r[176];unsigned int round;if(k==NULL||in==NULL||out==NULL)return false;expand(k,r);memcpy(s,in,16U);add(s,r);for(round=1U;round<10U;round++){sub(s);shift(s);mix(s);add(s,r+(size_t)round*16U);}sub(s);shift(s);add(s,r+160U);memcpy(out,s,16U);wipe(s,sizeof(s));wipe(r,sizeof(r));return true;}
static void dbl(const uint8_t in[16],uint8_t out[16]){uint8_t carry=0U;size_t i=16U;while(i--!=0U){uint8_t n=(uint8_t)(in[i]>>7U);out[i]=(uint8_t)((uint8_t)(in[i]<<1U)|carry);carry=n;}}
bool link_aes_cmac_128(const uint8_t k[16],const uint8_t*m,size_t len,uint8_t tag[16]){uint8_t z[16]={0},l[16],k1[16],k2[16],x[16]={0},y[16],last[16]={0};size_t n,b,rem;bool complete;if(k==NULL||tag==NULL||(len!=0U&&m==NULL))return false;if(!link_aes128_encrypt_block(k,z,l))return false;dbl(l,k1);if((l[0]&0x80U)!=0U)k1[15]^=0x87U;dbl(k1,k2);if((k1[0]&0x80U)!=0U)k2[15]^=0x87U;n=len/16U;rem=len%16U;complete=len!=0U&&rem==0U;if(rem!=0U)n++;if(n==0U)n=1U;if(complete){memcpy(last,m+(n-1U)*16U,16U);for(b=0;b<16U;b++)last[b]^=k1[b];}else{if(rem!=0U)memcpy(last,m+(n-1U)*16U,rem);last[rem]=0x80U;for(b=0;b<16U;b++)last[b]^=k2[b];}for(b=0;b+1U<n;b++){size_t i;for(i=0;i<16U;i++)y[i]=x[i]^m[b*16U+i];if(!link_aes128_encrypt_block(k,y,x))return false;}for(b=0;b<16U;b++)y[b]=x[b]^last[b];if(!link_aes128_encrypt_block(k,y,tag))return false;wipe(l,sizeof(l));wipe(k1,sizeof(k1));wipe(k2,sizeof(k2));wipe(x,sizeof(x));wipe(y,sizeof(y));wipe(last,sizeof(last));return true;}
bool link_aes_cmac_128_verify(const uint8_t k[16],const uint8_t*m,size_t len,const uint8_t expected[16]){uint8_t actual[16],diff=0U;size_t i;if(expected==NULL||!link_aes_cmac_128(k,m,len,actual))return false;for(i=0;i<16U;i++)diff|=(uint8_t)(actual[i]^expected[i]);wipe(actual,sizeof(actual));return diff==0U;}
